events = [
    {"_id": "1", "op": "insert", "ts": 1, "doc": {"v": "A"}},
    {"_id": "2", "op": "insert", "ts": 2, "doc": {"v": "X"}},
    {"_id": "1", "op": "update", "ts": 3, "doc": {"v": "B"}},
    {"_id": "2", "op": "delete", "ts": 4, "doc": None},
    {"_id": "1", "op": "update", "ts": 5, "doc": {"v": "C"}},
    {"_id": "1", "op": "update", "ts": 3, "doc": {"v": "B"}},  # 늦게 다시 온 중복
]
snapshot = {"3": {"v": "old"}}          # 처음 한 번 통째로 받은 것
last = {}
for e in events:
    if e["_id"] not in last or e["ts"] > last[e["_id"]]["ts"]:
        last[e["_id"]] = e
final = dict(snapshot)
for pk, e in last.items():
    if e["op"] == "delete":
        final.pop(pk, None)
    else:
        final[pk] = e["doc"]
print(sorted(final.items()))
